mapper.insert:
INSERT INTO external_benchmark_sync_runs (
    company_id, base_year, industry_code, status, triggered_by, started_at
) VALUES (
    #{companyId}, #{baseYear}, #{industryCode}, #{status}, #{triggeredBy}, CURRENT_TIMESTAMP
)

mapper.update:
UPDATE external_benchmark_sync_runs
SET status = #{status},
    completed_at = CURRENT_TIMESTAMP,
    error_message = #{errorMessage}
WHERE id = #{id}

mapper.select:
SELECT id, company_id, source_code, dataset_code, metric_code, base_year,
       industry_code, industry_name, original_value, original_unit,
       normalized_value, normalized_unit, source_updated_at,
       raw_payload::text AS raw_payload, synced_at, sync_run_id
FROM external_benchmark_values
WHERE company_id = #{companyId}
  AND base_year = #{baseYear}
  AND industry_code = #{industryCode}
  AND metric_code = #{metricCode}
ORDER BY synced_at DESC
LIMIT 1
